import openpyxl
wb = openpyxl.load_workbook('init.xlsx')
ws = wb['Sheet1']
for r in range(2, 67):
    if ws.cell(row=r, column=2).value == 1:
        prev = None
        cnt = 0
        for rr in range(2, r):
            if ws.cell(row=rr, column=2).value == 1:
                prev = rr
        for rr in range((prev+1) if prev is not None else 2, r):
            v = ws.cell(row=rr, column=1).value
            if v is not None and v > 0:
                cnt += 1
        ws.cell(row=r, column=3).value = cnt
wb.save('output.xlsx')
print("done")
EOF
python3 solve.py
